"use client";

import { use, useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { ArrowLeft, MapPin, CreditCard, ShoppingBag, Package, Truck, CheckCircle2, AlertCircle, Loader2 } from 'lucide-react';
import { useVoice } from '@/context/VoiceContext';

export default function OrderDetailsPage({ params }) {
    const { id } = use(params);
    const router = useRouter();
    const { speak } = useVoice();
    const [order, setOrder] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchOrder = async () => {
            try {
                const res = await fetch(`/api/orders/${id}`);
                if (!res.ok) {
                    if (res.status === 404) throw new Error("Order not found");
                    if (res.status === 403) throw new Error("Access denied");
                    throw new Error("Failed to load order");
                }
                const data = await res.json();
                setOrder(data);
                speak(`Showing details for order ${id.slice(-4)}`);
            } catch (err) {
                setError(err.message);
            } finally {
                setLoading(false);
            }
        };

        if (id) fetchOrder();
    }, [id]);

    if (loading) {
        return (
            <div className="min-h-screen bg-gray-50 flex items-center justify-center">
                <Loader2 className="w-8 h-8 animate-spin text-primary" />
            </div>
        );
    }

    if (error) {
        return (
            <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4">
                <AlertCircle className="w-12 h-12 text-red-500 mb-4" />
                <h1 className="text-xl font-bold text-gray-800 mb-2">Error Loading Order</h1>
                <p className="text-gray-600 mb-6">{error}</p>
                <Link href="/account" className="btn btn-primary">Back to Account</Link>
            </div>
        );
    }

    if (!order) return null;

    const steps = ['Processing', 'Shipped', 'Out for Delivery', 'Delivered'];
    const currentStepIndex = steps.indexOf(order.status) !== -1 ? steps.indexOf(order.status) : 0;
    const isCancelled = order.status === 'Cancelled';

    return (
        <div className="min-h-screen bg-gray-50 py-8 px-4">
            <div className="max-w-3xl mx-auto space-y-6">

                {/* Header */}
                <div className="flex items-center gap-4">
                    <Link href="/account" className="p-2 hover:bg-white rounded-full transition-colors">
                        <ArrowLeft className="w-5 h-5 text-gray-600" />
                    </Link>
                    <div>
                        <h1 className="text-2xl font-bold text-gray-900">Order Details</h1>
                        <p className="text-sm text-muted-foreground">ID: #{order._id}</p>
                    </div>
                </div>

                {/* Status Card */}
                <div className="bg-white rounded-xl shadow-sm border border-border p-6">
                    <div className="flex items-center justify-between mb-6">
                        <h2 className="font-bold text-lg flex items-center gap-2">
                            <Package className="w-5 h-5 text-primary" />
                            Order Status
                        </h2>
                        <span className={`px-3 py-1 rounded-full text-sm font-medium ${order.status === 'Delivered' ? 'bg-green-100 text-green-700' :
                                order.status === 'Cancelled' ? 'bg-red-100 text-red-700' :
                                    'bg-blue-100 text-blue-700'
                            }`}>
                            {order.status}
                        </span>
                    </div>

                    {!isCancelled && (
                        <div className="relative flex justify-between">
                            <div className="absolute top-1/2 left-0 w-full h-1 bg-gray-100 -z-10 -translate-y-1/2" />
                            <div
                                className="absolute top-1/2 left-0 h-1 bg-primary -z-10 -translate-y-1/2 transition-all duration-500"
                                style={{ width: `${(currentStepIndex / (steps.length - 1)) * 100}%` }}
                            />

                            {steps.map((step, idx) => {
                                const isCompleted = idx <= currentStepIndex;
                                return (
                                    <div key={step} className="flex flex-col items-center gap-2 bg-white px-2">
                                        <div className={`w-8 h-8 rounded-full flex items-center justify-center border-2 ${isCompleted ? 'bg-primary border-primary text-white' : 'bg-white border-gray-200 text-gray-300'
                                            }`}>
                                            {isCompleted ? <CheckCircle2 className="w-4 h-4" /> : <div className="w-2 h-2 rounded-full bg-gray-200" />}
                                        </div>
                                        <span className={`text-xs font-medium ${isCompleted ? 'text-gray-900' : 'text-gray-400'}`}>{step}</span>
                                    </div>
                                )
                            })}
                        </div>
                    )}
                </div>

                {/* Items */}
                <div className="bg-white rounded-xl shadow-sm border border-border p-6">
                    <h2 className="font-bold text-lg flex items-center gap-2 mb-4">
                        <ShoppingBag className="w-5 h-5 text-primary" />
                        Items ({order.items.length})
                    </h2>
                    <div className="space-y-4">
                        {order.items.map((item, index) => (
                            <div key={index} className="flex gap-4 py-4 border-b last:border-0 hover:bg-gray-50/50 rounded-lg p-2 transition-colors">
                                <Link href={`/shop/${item.productId}`} className="w-16 h-16 bg-gray-100 rounded-md border flex-shrink-0">
                                    <img src={item.image} alt={item.name} className="w-full h-full object-contain" />
                                </Link>
                                <div className="flex-1">
                                    <Link href={`/shop/${item.productId}`} className="font-medium hover:text-primary transition-colors">
                                        {item.name}
                                    </Link>
                                    <p className="text-sm text-muted-foreground mt-1">
                                        {item.selectedOptions?.size && `Size: ${item.selectedOptions.size}`}
                                        {item.selectedOptions?.color && ` • Color: ${item.selectedOptions.color}`}
                                    </p>
                                    <div className="flex justify-between items-center mt-2">
                                        <p className="text-sm text-gray-600">Qty: {item.quantity}</p>
                                        <p className="font-bold">₹{(item.price * item.quantity).toLocaleString()}</p>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Shipping & Payment Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* Shipping Address */}
                    <div className="bg-white rounded-xl shadow-sm border border-border p-6">
                        <h2 className="font-bold text-lg flex items-center gap-2 mb-4">
                            <MapPin className="w-5 h-5 text-primary" />
                            Shipping Address
                        </h2>
                        <div className="text-sm text-gray-600 space-y-1">
                            <p className="font-bold text-gray-900">{order.shippingAddress.name}</p>
                            <p>{order.shippingAddress.street}</p>
                            <p>{order.shippingAddress.city}, {order.shippingAddress.pincode}</p>
                            <p className="mt-2 text-gray-500">Phone: {order.shippingAddress.phone}</p>
                        </div>
                    </div>

                    {/* Payment Info */}
                    <div className="bg-white rounded-xl shadow-sm border border-border p-6">
                        <h2 className="font-bold text-lg flex items-center gap-2 mb-4">
                            <CreditCard className="w-5 h-5 text-primary" />
                            Payment Details
                        </h2>
                        <div className="space-y-3">
                            <div className="flex justify-between text-sm">
                                <span className="text-gray-600">Method</span>
                                <span className="font-medium uppercase">{order.paymentMethod}</span>
                            </div>
                            <div className="flex justify-between text-sm">
                                <span className="text-gray-600">Order Total</span>
                                <span className="font-bold text-lg">₹{order.total.toLocaleString()}</span>
                            </div>
                            <div className="flex items-center gap-2 mt-4 text-xs text-green-700 bg-green-50 p-2 rounded">
                                <CheckCircle2 className="w-4 h-4" />
                                <span>Payment Verified</span>
                            </div>
                        </div>
                    </div>
                </div>

            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from 'react';
import { useVoice } from '@/context/VoiceContext';
import { useAuth } from '@/context/AuthContext';
import { useWishlist } from '@/context/WishlistContext';
import { useCart } from '@/context/CartContext';
import { useRouter } from 'next/navigation';
import { User, Package, Heart, CreditCard, MapPin, LogOut, ChevronRight, Box, Loader2, AlertCircle, CheckCircle2, Trash2, Plus } from 'lucide-react';
import Link from 'next/link';

export default function AccountPage() {
    const { speak } = useVoice();
    const { logout, user } = useAuth();
    const { wishlist } = useWishlist();
    const { addToCart } = useCart();
    const router = useRouter();
    const [activeTab, setActiveTab] = useState('profile');

    // Orders State
    const [orders, setOrders] = useState([]);
    const [loadingOrders, setLoadingOrders] = useState(true);

    // Tracking State
    const [trackOrderId, setTrackOrderId] = useState('');
    const [trackedOrder, setTrackedOrder] = useState(null);
    const [trackingLoading, setTrackingLoading] = useState(false);
    const [trackingError, setTrackingError] = useState(null);

    // Payments State
    const [paymentMethods, setPaymentMethods] = useState([]);
    const [loadingPayments, setLoadingPayments] = useState(false);
    const [addingCard, setAddingCard] = useState(false);
    const [newCard, setNewCard] = useState({ holderName: '', last4: '', expiry: '' });

    const tabs = [
        { id: 'profile', label: 'Profile', icon: User },
        { id: 'orders', label: 'My Orders', icon: Package },
        { id: 'favorites', label: 'Favorites', icon: Heart },
        { id: 'payments', label: 'Payments', icon: CreditCard },
        { id: 'tracking', label: 'Order Tracking', icon: MapPin },
    ];

    useEffect(() => {
        const fetchOrders = async () => {
            try {
                const res = await fetch('/api/orders');
                if (res.ok) {
                    const data = await res.json();
                    setOrders(data);
                }
            } catch (error) {
                console.error("Failed to fetch orders", error);
            } finally {
                setLoadingOrders(false);
            }
        };

        if (user) {
            fetchOrders();
        } else {
            setLoadingOrders(false);
        }
    }, [user]);

    // Fetch payments when tab is active
    useEffect(() => {
        if (activeTab === 'payments' && user) {
            setLoadingPayments(true);
            fetch('/api/user/payment-methods')
                .then(res => res.json())
                .then(data => setPaymentMethods(data))
                .catch(err => console.error(err))
                .finally(() => setLoadingPayments(false));
        }
    }, [activeTab, user]);

    const handleTabChange = (tabId) => {
        setActiveTab(tabId);
        speak(`Showing ${tabId}`);
    };

    const handleLogout = () => {
        logout();
        speak("Signed out successfully.");
        router.push('/');
    };

    const handleTrackOrder = async () => {
        if (!trackOrderId.trim()) {
            setTrackingError("Please enter an Order ID");
            return;
        }

        setTrackingLoading(true);
        setTrackingError(null);
        setTrackedOrder(null);

        try {
            const res = await fetch(`/api/orders/${trackOrderId.trim()}`);

            if (!res.ok) {
                if (res.status === 404) throw new Error("Order not found. Please check the ID.");
                if (res.status === 403) throw new Error("You don't have permission to view this order.");
                throw new Error("Failed to track order");
            }

            const data = await res.json();
            setTrackedOrder(data);
            speak(`Order found. Status is ${data.status}`);
        } catch (err) {
            setTrackingError(err.message);
            speak("Could not track order.");
        } finally {
            setTrackingLoading(false);
        }
    };

    const handleAddCard = async (e) => {
        e.preventDefault();
        try {
            const res = await fetch('/api/user/payment-methods', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(newCard)
            });
            if (res.ok) {
                const updatedMethods = await res.json();
                setPaymentMethods(updatedMethods);
                setAddingCard(false);
                setNewCard({ holderName: '', last4: '', expiry: '' });
                speak("Payment method added.");
            }
        } catch (error) {
            console.error("Failed to add card", error);
        }
    };

    const handleDeleteCard = async (id) => {
        try {
            const res = await fetch('/api/user/payment-methods', {
                method: 'DELETE',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id })
            });
            if (res.ok) {
                const updatedMethods = await res.json();
                setPaymentMethods(updatedMethods);
                speak("Payment method removed.");
            }
        } catch (error) {
            console.error("Failed to delete card", error);
        }
    };

    return (
        <div className="container py-8 min-h-[80vh]">
            <div className="grid grid-cols-1 md:grid-cols-12 gap-8">

                {/* Sidebar Navigation */}
                <div className="md:col-span-3 space-y-2">
                    <div className="p-4 bg-secondary/30 rounded-xl mb-6 flex items-center gap-3">
                        <div className="w-12 h-12 rounded-full bg-primary text-primary-foreground flex items-center justify-center text-xl font-bold">
                            {user?.name ? user.name.charAt(0).toUpperCase() : 'U'}
                        </div>
                        <div>
                            <h2 className="font-bold">{user?.name || 'Guest User'}</h2>
                            <p className="text-xs text-muted-foreground">{user?.email || 'guest@example.com'}</p>
                        </div>
                    </div>

                    <nav className="space-y-1">
                        {tabs.map((tab) => (
                            <button
                                key={tab.id}
                                onClick={() => handleTabChange(tab.id)}
                                className={`w-full flex items-center gap-3 px-4 py-3 text-sm font-medium rounded-lg transition-colors ${activeTab === tab.id
                                    ? 'bg-primary text-primary-foreground'
                                    : 'hover:bg-secondary text-muted-foreground'
                                    }`}
                            >
                                <tab.icon className="w-4 h-4" />
                                {tab.label}
                            </button>
                        ))}
                        <button
                            onClick={handleLogout}
                            className="w-full flex items-center gap-3 px-4 py-3 text-sm font-medium rounded-lg text-destructive hover:bg-destructive/10 transition-colors mt-4"
                        >
                            <LogOut className="w-4 h-4" />
                            Sign Out
                        </button>
                    </nav>
                </div>

                {/* Main Content Area */}
                <div className="md:col-span-9">
                    <div className="bg-card border border-border rounded-2xl p-6 md:p-8 shadow-sm min-h-[500px]">

                        {activeTab === 'profile' && (
                            <div className="space-y-6 animate-fadeIn animate-slideUp">
                                <h2 className="text-2xl font-bold">Personal Information</h2>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium text-muted-foreground">Full Name</label>
                                        <input type="text" defaultValue={user?.name || ''} className="w-full p-2 rounded-md border bg-background" />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium text-muted-foreground">Email</label>
                                        <input type="email" defaultValue={user?.email || ''} className="w-full p-2 rounded-md border bg-background" />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium text-muted-foreground">Phone</label>
                                        <input type="tel" defaultValue={user?.phone || ''} placeholder="+91 98765 43210" className="w-full p-2 rounded-md border bg-background" />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium text-muted-foreground">Location</label>
                                        <input type="text" defaultValue={user?.location || ''} placeholder="New Delhi, India" className="w-full p-2 rounded-md border bg-background" />
                                    </div>
                                </div>
                                <button className="btn btn-primary">Save Changes</button>
                            </div>
                        )}

                        {activeTab === 'orders' && (
                            <div className="space-y-6 animate-fadeIn animate-slideUp">
                                <h2 className="text-2xl font-bold">My Orders</h2>
                                {loadingOrders ? (
                                    <div className="flex justify-center p-8">
                                        <Loader2 className="w-8 h-8 animate-spin text-primary" />
                                    </div>
                                ) : orders.length === 0 ? (
                                    <div className="text-center py-12 text-muted-foreground">
                                        <Package className="w-12 h-12 mx-auto mb-4 opacity-50" />
                                        <p>You haven't placed any orders yet.</p>
                                        <Link href="/shop" className="text-primary hover:underline mt-2 inline-block">Start Shopping</Link>
                                    </div>
                                ) : (
                                    <div className="space-y-4">
                                        {orders.map((order) => (
                                            <div key={order._id} className="border rounded-xl p-4 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                                                <div>
                                                    <div className="flex items-center gap-2 mb-1">
                                                        <span className="font-bold">ORD-{order._id.slice(-6).toUpperCase()}</span>
                                                        <span className={`text-xs px-2 py-0.5 rounded-full ${order.status === 'Delivered' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>
                                                            {order.status}
                                                        </span>
                                                    </div>
                                                    <p className="text-sm text-muted-foreground">
                                                        {new Date(order.createdAt).toLocaleDateString()} • {order.items.length} items
                                                    </p>
                                                    <p className="text-xs text-muted-foreground truncate max-w-xs">
                                                        {order.items.map(i => i.name).join(', ')}
                                                    </p>
                                                </div>
                                                <div className="flex items-center gap-4 w-full md:w-auto justify-between">
                                                    <span className="font-bold">₹{order.total.toLocaleString()}</span>
                                                    <Link href={`/account/orders/${order._id}`} className="text-sm text-primary hover:underline" onClick={() => speak(`Viewing order details`)}>
                                                        View Details
                                                    </Link>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        )}

                        {activeTab === 'favorites' && (
                            <div className="space-y-6 animate-fadeIn animate-slideUp">
                                <h2 className="text-2xl font-bold">Favorites</h2>
                                {wishlist.length === 0 ? (
                                    <div className="text-center py-12 text-muted-foreground border-2 border-dashed rounded-xl">
                                        <Heart className="w-12 h-12 mx-auto mb-4 opacity-20" />
                                        <p>Your wishlist is empty.</p>
                                        <Link href="/shop" className="text-primary hover:underline mt-2 inline-block font-medium">
                                            Discover Products
                                        </Link>
                                    </div>
                                ) : (
                                    <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                                        {wishlist.map((item) => (
                                            <div key={item.id} className="group border rounded-xl p-4 hover:shadow-md transition-shadow">
                                                <Link href={`/shop/${item.id}`}>
                                                    <div className="aspect-square bg-secondary/30 rounded-lg mb-3 overflow-hidden relative">
                                                        <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform" />
                                                    </div>
                                                </Link>
                                                <Link href={`/shop/${item.id}`} className="hover:underline">
                                                    <h3 className="font-medium truncate">{item.name}</h3>
                                                </Link>
                                                <p className="text-sm text-muted-foreground">₹{item.price.toLocaleString()}</p>
                                                <button
                                                    onClick={() => {
                                                        addToCart(item);
                                                        speak(`Added ${item.name} to cart`);
                                                    }}
                                                    className="mt-3 w-full text-xs btn btn-outline h-8 hover:bg-primary hover:text-white transition-colors"
                                                >
                                                    Add to Cart
                                                </button>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        )}

                        {activeTab === 'payments' && (
                            <div className="space-y-6 animate-fadeIn animate-slideUp">
                                <h2 className="text-2xl font-bold">Payment Methods</h2>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    {paymentMethods.map((method) => (
                                        <div key={method._id} className="border rounded-xl p-6 bg-gradient-to-br from-gray-900 to-gray-800 text-white relative overflow-hidden group">
                                            <button
                                                onClick={() => handleDeleteCard(method._id)}
                                                className="absolute top-2 right-2 p-2 opacity-0 group-hover:opacity-100 transition-opacity hover:bg-white/20 rounded-full"
                                                title="Remove Card"
                                            >
                                                <Trash2 className="w-4 h-4 text-red-300" />
                                            </button>
                                            <div className="absolute top-0 right-0 p-4 opacity-20 pointer-events-none">
                                                <CreditCard className="w-24 h-24" />
                                            </div>
                                            <div className="relative z-10">
                                                <p className="text-xs opacity-70 mb-8">Debit/Credit Card</p>
                                                <p className="text-2xl font-mono mb-8">**** **** **** {method.last4}</p>
                                                <div className="flex justify-between items-end">
                                                    <div>
                                                        <p className="text-xs opacity-70">Card Holder</p>
                                                        <p className="font-medium uppercase">{method.holderName}</p>
                                                    </div>
                                                    <div>
                                                        <p className="text-xs opacity-70">Expires</p>
                                                        <p className="font-medium">{method.expiry}</p>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    ))}

                                    {!addingCard ? (
                                        <button
                                            onClick={() => setAddingCard(true)}
                                            className="border rounded-xl p-6 flex items-center justify-center border-dashed cursor-pointer hover:bg-secondary/50 transition-colors min-h-[220px]"
                                        >
                                            <div className="text-center">
                                                <div className="w-10 h-10 rounded-full bg-secondary flex items-center justify-center mx-auto mb-2">
                                                    <Plus className="w-6 h-6" />
                                                </div>
                                                <p className="text-sm font-medium">Add New Card</p>
                                            </div>
                                        </button>
                                    ) : (
                                        <div className="border rounded-xl p-6 bg-secondary/10">
                                            <h3 className="font-bold mb-4">Add Card Details</h3>
                                            <form onSubmit={handleAddCard} className="space-y-3">
                                                <input
                                                    className="w-full p-2 rounded border text-sm"
                                                    placeholder="Card Holder Name"
                                                    value={newCard.holderName}
                                                    onChange={e => setNewCard({ ...newCard, holderName: e.target.value })}
                                                    required
                                                />
                                                <div className="flex gap-2">
                                                    <input
                                                        className="w-full p-2 rounded border text-sm"
                                                        placeholder="Last 4 Digits"
                                                        maxLength={4}
                                                        value={newCard.last4}
                                                        onChange={e => setNewCard({ ...newCard, last4: e.target.value })}
                                                        required
                                                    />
                                                    <input
                                                        className="w-full p-2 rounded border text-sm"
                                                        placeholder="MM/YY"
                                                        value={newCard.expiry}
                                                        onChange={e => setNewCard({ ...newCard, expiry: e.target.value })}
                                                        required
                                                    />
                                                </div>
                                                <div className="flex gap-2 mt-2">
                                                    <button type="submit" className="flex-1 btn btn-primary text-xs py-2">Save</button>
                                                    <button
                                                        type="button"
                                                        onClick={() => setAddingCard(false)}
                                                        className="flex-1 btn btn-outline text-xs py-2"
                                                    >
                                                        Cancel
                                                    </button>
                                                </div>
                                            </form>
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}

                        {activeTab === 'tracking' && (
                            <div className="space-y-6 animate-fadeIn animate-slideUp">
                                <h2 className="text-2xl font-bold">Track Order</h2>
                                <div className="flex gap-2 mb-6">
                                    <input
                                        type="text"
                                        placeholder="Enter Order ID"
                                        className="flex-1 p-2 rounded-md border bg-background"
                                        value={trackOrderId}
                                        onChange={(e) => setTrackOrderId(e.target.value)}
                                    />
                                    <button
                                        onClick={handleTrackOrder}
                                        disabled={trackingLoading}
                                        className="btn btn-primary px-6 disabled:opacity-50"
                                    >
                                        {trackingLoading ? 'Tracking...' : 'Track'}
                                    </button>
                                </div>

                                {trackingError && (
                                    <div className="p-4 bg-red-50 text-red-600 rounded-lg flex items-center gap-2">
                                        <AlertCircle className="w-5 h-5" />
                                        {trackingError}
                                    </div>
                                )}

                                {trackedOrder && (
                                    <div className="border rounded-xl p-6 space-y-8 animate-in fade-in slide-in-from-bottom-4">
                                        <div className="flex items-center justify-between border-b pb-4">
                                            <div>
                                                <h3 className="font-bold text-lg">Order #{trackedOrder._id}</h3>
                                                <p className="text-sm text-muted-foreground">
                                                    Status: <span className="font-medium text-foreground">{trackedOrder.status}</span>
                                                </p>
                                            </div>
                                            <Box className="w-8 h-8 text-primary" />
                                        </div>

                                        <div className="relative space-y-8 pl-8 before:content-[''] before:absolute before:left-3 before:top-2 before:bottom-2 before:w-0.5 before:bg-border">
                                            {['Processing', 'Shipped', 'Out for Delivery', 'Delivered'].map((step, idx) => {
                                                const statuses = ['Processing', 'Shipped', 'Out for Delivery', 'Delivered'];
                                                const currentIdx = statuses.indexOf(trackedOrder.status);
                                                const isCompleted = idx <= currentIdx;
                                                const isActive = idx === currentIdx;

                                                return (
                                                    <div key={idx} className="relative">
                                                        <div className={`absolute -left-[29px] w-4 h-4 rounded-full border-2 transition-colors duration-500 ${isCompleted ? 'bg-primary border-primary' : 'bg-background border-muted'
                                                            }`} />
                                                        <h4 className={`font-medium ${isCompleted ? 'text-foreground' : 'text-muted-foreground'}`}>{step}</h4>
                                                        {isActive && <p className="text-xs text-primary font-medium animate-pulse">Current Status</p>}
                                                    </div>
                                                );
                                            })}
                                        </div>

                                        {trackedOrder.status === 'Delivered' && (
                                            <div className="bg-green-50 p-4 rounded-lg flex items-center gap-2 text-green-700 text-sm">
                                                <CheckCircle2 className="w-5 h-5" />
                                                Your order has been delivered successfully.
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>
                        )}

                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import React from 'react';
import { useCart } from '@/context/CartContext';
import { useVoice } from '@/context/VoiceContext';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { Trash2, Minus, Plus } from 'lucide-react';

export default function Cart() {
    const { cart, removeFromCart, clearCart, total, updateQuantity } = useCart();
    const { speak } = useVoice();

    const router = useRouter();

    // Voice Command Listeners
    React.useEffect(() => {
        const handleInc = () => {
            if (cart.length > 0) {
                const item = cart[0]; // Target first item for now
                updateQuantity(item.cartItemId, item.quantity + 1);
                speak(`Increased quantity for ${item.name}`);
            } else {
                speak("Cart is empty.");
            }
        };

        const handleDec = () => {
            if (cart.length > 0) {
                const item = cart[0];
                if (item.quantity > 1) {
                    updateQuantity(item.cartItemId, item.quantity - 1);
                    speak(`Decreased quantity for ${item.name}`);
                } else {
                    speak("Quantity is already at minimum. Say 'remove this' to delete.");
                }
            }
        };

        const handleClear = () => {
            if (cart.length > 0) {
                clearCart();
                speak("Cart cleared.");
            }
        };

        window.addEventListener('TRIGGER_INC_QTY', handleInc);
        window.addEventListener('TRIGGER_DEC_QTY', handleDec);
        // window.addEventListener('TRIGGER_CLEAR_CART', handleClear); // If we added this action

        return () => {
            window.removeEventListener('TRIGGER_INC_QTY', handleInc);
            window.removeEventListener('TRIGGER_DEC_QTY', handleDec);
        };
    }, [cart, updateQuantity]);

    const handleCheckout = () => {
        if (cart.length === 0) {
            speak("Your cart is empty.");
            return;
        }
        speak(`Proceeding to checkout. Your total is ₹${total.toFixed(2)}.`);
        router.push('/checkout');
    };

    const handleRemove = (item) => {
        removeFromCart(item.cartItemId);
        speak(`Removed ${item.name} from cart.`);
    };

    return (
        <div className="max-w-4xl mx-auto">
            <h1 className="text-3xl font-bold mb-8">Your Cart</h1>

            {cart.length === 0 ? (
                <div className="text-center py-12">
                    <p className="text-xl text-muted-foreground mb-6">Your cart is empty.</p>
                    <Link href="/shop" className="btn btn-primary">
                        Continue Shopping
                    </Link>
                </div>
            ) : (
                <div className="grid gap-8 md:grid-cols-3">
                    <div className="md:col-span-2 space-y-4">
                        {cart.map((item) => (
                            <div key={item.cartItemId} className="flex items-center gap-4 p-4 border border-border rounded-lg bg-card">
                                <div className="w-20 h-20 bg-white rounded overflow-hidden flex items-center justify-center relative border border-gray-200">
                                    <img
                                        src={item.image}
                                        alt={item.name}
                                        className="w-full h-full object-cover"
                                    />
                                </div>
                                <div className="flex-1">
                                    <h3 className="font-bold">{item.name}</h3>
                                    <p className="text-muted-foreground">₹{item.price}</p>

                                    <div className="flex items-center gap-2 mt-2">
                                        <button
                                            onClick={() => updateQuantity(item.cartItemId, item.quantity - 1)}
                                            className="p-1 rounded-md hover:bg-secondary border border-border"
                                            disabled={item.quantity <= 1}
                                        >
                                            <Minus className="w-4 h-4" />
                                        </button>
                                        <span className="font-medium w-8 text-center">{item.quantity}</span>
                                        <button
                                            onClick={() => {
                                                updateQuantity(item.cartItemId, item.quantity + 1);
                                                speak("Quantity increased");
                                            }}
                                            className="p-1 rounded-md hover:bg-secondary border border-border"
                                        >
                                            <Plus className="w-4 h-4" />
                                        </button>
                                    </div>

                                    {item.selectedOptions && (
                                        <p className="text-xs text-muted-foreground mt-2">
                                            {item.selectedOptions.size && `Size: ${item.selectedOptions.size} `}
                                            {item.selectedOptions.color && `Color: ${item.selectedOptions.color}`}
                                        </p>
                                    )}
                                </div>
                                <button
                                    onClick={() => handleRemove(item)}
                                    className="p-2 text-destructive hover:bg-destructive/10 rounded-full"
                                    aria-label={`Remove ${item.name} from cart`}
                                >
                                    <Trash2 className="w-5 h-5" />
                                </button>
                            </div>
                        ))}
                    </div>

                    <div className="md:col-span-1">
                        <div className="p-6 border border-border rounded-lg bg-card sticky top-24">
                            <h2 className="text-xl font-bold mb-4">Summary</h2>
                            <div className="flex justify-between mb-2">
                                <span>Subtotal</span>
                                <span>₹{total.toFixed(2)}</span>
                            </div>
                            <div className="flex justify-between mb-4 text-muted-foreground">
                                <span>Tax (Est.)</span>
                                <span>₹0.00</span>
                            </div>
                            <div className="border-t border-border my-4 pt-4 flex justify-between font-bold text-lg">
                                <span>Total</span>
                                <span>₹{total.toFixed(2)}</span>
                            </div>

                            <button
                                onClick={handleCheckout}
                                className="w-full btn btn-primary mb-4"
                            >
                                Checkout
                            </button>

                            <button
                                onClick={clearCart}
                                className="w-full btn btn-secondary text-sm"
                            >
                                Clear Cart
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect } from 'react';
import { useVoice } from '@/context/VoiceContext';
import { useCart } from '@/context/CartContext';
import { useAuth } from '@/context/AuthContext';
import { Check, CreditCard, Truck, ShieldCheck, Smartphone, MapPin, ShoppingBag, Loader2 } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';

export default function CheckoutPage() {
    const { speak } = useVoice();
    const { cart, total, clearCart } = useCart();
    const { user, isAuthenticated } = useAuth();
    const router = useRouter();

    // Steps: 1 = Address, 2 = Order Summary, 3 = Payment, 4 = Success
    const [currentStep, setCurrentStep] = useState(1);

    // Address State
    const [address, setAddress] = useState({
        name: 'Harsh',
        street: '123, Green Park',
        city: 'New Delhi',
        pincode: '110016',
        phone: '9876543210'
    });

    // Payment State
    const [paymentMethod, setPaymentMethod] = useState('upi');
    const [isOrderPlaced, setIsOrderPlaced] = useState(false);
    const [orderId, setOrderId] = useState(null);
    const [isProcessing, setIsProcessing] = useState(false);

    useEffect(() => {
        // Redirect if not authenticated (optional, depends on policy)
        // For now, we assume middleware or user will login. 
        // We can show a prompt if not logged in.
    }, [isAuthenticated]);

    const steps = [
        { id: 1, label: "Address", icon: MapPin },
        { id: 2, label: "Summary", icon: ShoppingBag },
        { id: 3, label: "Payment", icon: CreditCard },
    ];

    const handleNext = () => {
        if (currentStep < 3) {
            setCurrentStep(curr => curr + 1);
            if (currentStep === 1) speak("Address confirmed. Review your order.");
            if (currentStep === 2) speak("Order reviewed. Choose payment method.");
        }
    };

    const handleBack = () => {
        if (currentStep > 1) setCurrentStep(curr => curr - 1);
    };

    const handlePlaceOrder = async () => {
        if (!user) {
            speak("Please sign in to place your order.");
            router.push('/signin?redirect=/checkout');
            return;
        }

        setIsProcessing(true);
        speak("Processing your order. Please wait.");

        try {
            const orderData = {
                items: cart.map(item => ({
                    productId: item.id,
                    name: item.name,
                    price: item.price,
                    quantity: item.quantity,
                    image: item.image,
                    selectedOptions: item.selectedOptions
                })),
                total: total,
                shippingAddress: address,
                paymentMethod: paymentMethod
            };

            const res = await fetch('/api/orders', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(orderData)
            });

            if (res.ok) {
                const data = await res.json();
                setOrderId(data._id);
                setIsOrderPlaced(true);
                setCurrentStep(4);
                clearCart();
                speak("Order placed successfully! Thank you for shopping.");
            } else {
                throw new Error('Failed to place order');
            }
        } catch (error) {
            console.error(error);
            speak("Sorry, there was an issue placing your order.");
            alert("Failed to place order. Please try again.");
        } finally {
            setIsProcessing(false);
        }
    };

    if (cart.length === 0 && !isOrderPlaced) {
        return (
            <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4">
                <div className="text-center space-y-4">
                    <div className="bg-white p-6 rounded-full inline-block shadow-sm">
                        <ShoppingBag className="w-12 h-12 text-gray-300" />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-800">Your cart is empty</h2>
                    <p className="text-gray-500">Add items to proceed to checkout.</p>
                    <Link href="/shop" className="btn btn-primary inline-block">Start Shopping</Link>
                </div>
            </div>
        );
    }

    if (isOrderPlaced) {
        return (
            <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4 animate-in fade-in duration-500">
                <div className="bg-white p-8 rounded-2xl shadow-lg max-w-md w-full text-center space-y-6 border border-border">
                    <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto">
                        <Check className="w-10 h-10 text-green-600" />
                    </div>
                    <div>
                        <h1 className="text-3xl font-bold text-gray-900 mb-2">Order Confirmed!</h1>
                        <p className="text-gray-600">Thank you for your purchase. Your order ID is <span className="font-mono font-bold text-gray-900">#{orderId ? orderId.slice(-6).toUpperCase() : 'ORD-1234'}</span></p>
                    </div>
                    <div className="bg-gray-50 p-4 rounded-xl text-left text-sm space-y-2">
                        <div className="flex justify-between">
                            <span className="text-muted-foreground">Amount Paid</span>
                            <span className="font-bold">₹{total.toLocaleString()}</span>
                        </div>
                        <div className="flex justify-between">
                            <span className="text-muted-foreground">Payment Method</span>
                            <span className="font-bold uppercase">{paymentMethod}</span>
                        </div>
                    </div>
                    <Link href="/shop" className="btn btn-primary w-full block">Continue Shopping</Link>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 py-8 px-4">
            <div className="max-w-4xl mx-auto">

                {/* Stepper Header */}
                <div className="mb-8">
                    <div className="flex items-center justify-between relative px-4 md:px-12">
                        {/* Progress Line */}
                        <div className="absolute left-0 top-1/2 -translate-y-1/2 w-full h-1 bg-gray-200 -z-10" />
                        <div
                            className="absolute left-0 top-1/2 -translate-y-1/2 h-1 bg-primary transition-all duration-500 -z-10"
                            style={{ width: `${((currentStep - 1) / 2) * 100}%` }}
                        />

                        {steps.map((step) => {
                            const isActive = currentStep >= step.id;
                            const isCurrent = currentStep === step.id;
                            const Icon = step.icon;

                            return (
                                <div key={step.id} className="flex flex-col items-center gap-2 bg-gray-50 px-2">
                                    <div
                                        className={`w-10 h-10 rounded-full flex items-center justify-center transition-all duration-300 ${isActive ? 'bg-primary text-white scale-110 shadow-lg' : 'bg-gray-200 text-gray-400'
                                            } ${isCurrent ? 'ring-4 ring-primary/20' : ''}`}
                                    >
                                        <Icon className="w-5 h-5" />
                                    </div>
                                    <span className={`text-xs font-bold uppercase tracking-wider ${isActive ? 'text-primary' : 'text-gray-400'}`}>
                                        {step.label}
                                    </span>
                                </div>
                            );
                        })}
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-12 gap-8">
                    {/* Main Content Area */}
                    <div className="md:col-span-8 space-y-6">

                        {/* Step 1: Address */}
                        {currentStep === 1 && (
                            <div className="bg-white rounded-xl shadow-sm border border-border p-6 animate-in slide-in-from-right-4 duration-300">
                                <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
                                    <MapPin className="text-primary w-5 h-5" />
                                    Shipping Address
                                </h2>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium">Full Name</label>
                                        <input
                                            type="text"
                                            value={address.name}
                                            onChange={(e) => setAddress({ ...address, name: e.target.value })}
                                            className="w-full h-10 px-3 border rounded-lg focus:border-primary focus:ring-2 focus:ring-primary/20 outline-none"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium">Phone Number</label>
                                        <input
                                            type="text"
                                            value={address.phone}
                                            onChange={(e) => setAddress({ ...address, phone: e.target.value })}
                                            className="w-full h-10 px-3 border rounded-lg focus:border-primary focus:ring-2 focus:ring-primary/20 outline-none"
                                        />
                                    </div>
                                    <div className="md:col-span-2 space-y-2">
                                        <label className="text-sm font-medium">Street Address</label>
                                        <input
                                            type="text"
                                            value={address.street}
                                            onChange={(e) => setAddress({ ...address, street: e.target.value })}
                                            className="w-full h-10 px-3 border rounded-lg focus:border-primary focus:ring-2 focus:ring-primary/20 outline-none"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium">City</label>
                                        <input
                                            type="text"
                                            value={address.city}
                                            onChange={(e) => setAddress({ ...address, city: e.target.value })}
                                            className="w-full h-10 px-3 border rounded-lg focus:border-primary focus:ring-2 focus:ring-primary/20 outline-none"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium">Pincode</label>
                                        <input
                                            type="text"
                                            value={address.pincode}
                                            onChange={(e) => setAddress({ ...address, pincode: e.target.value })}
                                            className="w-full h-10 px-3 border rounded-lg focus:border-primary focus:ring-2 focus:ring-primary/20 outline-none"
                                        />
                                    </div>
                                </div>
                                <div className="mt-8 flex justify-end">
                                    <button onClick={handleNext} className="btn btn-primary px-8">Save & Continue</button>
                                </div>
                            </div>
                        )}

                        {/* Step 2: Summary */}
                        {currentStep === 2 && (
                            <div className="bg-white rounded-xl shadow-sm border border-border p-6 animate-in slide-in-from-right-4 duration-300">
                                <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
                                    <ShoppingBag className="text-primary w-5 h-5" />
                                    Order Summary
                                </h2>
                                <div className="space-y-4 mb-8">
                                    {cart.map((item) => (
                                        <div key={item.cartItemId} className="flex gap-4 p-4 border rounded-lg bg-gray-50/50">
                                            <div className="w-20 h-20 bg-white rounded-md border flex-shrink-0">
                                                <img src={item.image} alt={item.name} className="w-full h-full object-contain" />
                                            </div>
                                            <div className="flex-1">
                                                <h3 className="font-semibold">{item.name}</h3>
                                                <p className="text-sm text-muted-foreground">{item.selectedOptions?.size && `Size: ${item.selectedOptions.size}`} {item.selectedOptions?.color && `• Color: ${item.selectedOptions.color}`}</p>
                                                <div className="flex items-center justify-between mt-2">
                                                    <span className="text-sm text-gray-600">Qty: {item.quantity}</span>
                                                    <span className="font-bold text-primary">₹{(item.price * item.quantity).toLocaleString()}</span>
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                                <div className="flex justify-between pt-4 border-t">
                                    <button onClick={handleBack} className="text-gray-500 font-medium hover:text-gray-900">Back</button>
                                    <button onClick={handleNext} className="btn btn-primary px-8">Continue to Payment</button>
                                </div>
                            </div>
                        )}

                        {/* Step 3: Payment */}
                        {currentStep === 3 && (
                            <div className="bg-white rounded-xl shadow-sm border border-border p-6 animate-in slide-in-from-right-4 duration-300">
                                <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
                                    <CreditCard className="text-primary w-5 h-5" />
                                    Select Payment Method
                                </h2>

                                <div className="space-y-3 mb-8">
                                    {/* UPI */}
                                    <label className={`block p-4 border rounded-xl cursor-pointer transition-all ${paymentMethod === 'upi' ? 'border-primary bg-primary/5 ring-1 ring-primary' : 'hover:border-primary/50'}`}>
                                        <div className="flex items-center gap-4">
                                            <input type="radio" name="payment" className="w-5 h-5 accent-primary" checked={paymentMethod === 'upi'} onChange={() => setPaymentMethod('upi')} />
                                            <div className="p-2 bg-white rounded-full border shadow-sm"><Smartphone className="w-5 h-5 text-purple-600" /></div>
                                            <div className="flex-1">
                                                <span className="font-semibold block">UPI</span>
                                                <span className="text-xs text-muted-foreground">Google Pay, PhonePe, Paytm</span>
                                            </div>
                                        </div>
                                    </label>

                                    {/* Card */}
                                    <label className={`block p-4 border rounded-xl cursor-pointer transition-all ${paymentMethod === 'card' ? 'border-primary bg-primary/5 ring-1 ring-primary' : 'hover:border-primary/50'}`}>
                                        <div className="flex items-center gap-4">
                                            <input type="radio" name="payment" className="w-5 h-5 accent-primary" checked={paymentMethod === 'card'} onChange={() => setPaymentMethod('card')} />
                                            <div className="p-2 bg-white rounded-full border shadow-sm"><CreditCard className="w-5 h-5 text-blue-600" /></div>
                                            <div className="flex-1">
                                                <span className="font-semibold block">Credit / Debit Card</span>
                                                <span className="text-xs text-muted-foreground">Visa, Mastercard, RuPay</span>
                                            </div>
                                        </div>
                                    </label>

                                    {/* COD */}
                                    <label className={`block p-4 border rounded-xl cursor-pointer transition-all ${paymentMethod === 'cod' ? 'border-primary bg-primary/5 ring-1 ring-primary' : 'hover:border-primary/50'}`}>
                                        <div className="flex items-center gap-4">
                                            <input type="radio" name="payment" className="w-5 h-5 accent-primary" checked={paymentMethod === 'cod'} onChange={() => setPaymentMethod('cod')} />
                                            <div className="p-2 bg-white rounded-full border shadow-sm"><Truck className="w-5 h-5 text-green-600" /></div>
                                            <div className="flex-1">
                                                <span className="font-semibold block">Cash on Delivery</span>
                                                <span className="text-xs text-muted-foreground">Pay when your order arrives</span>
                                            </div>
                                        </div>
                                    </label>
                                </div>

                                <div className="flex justify-between pt-4 border-t">
                                    <button onClick={handleBack} disabled={isProcessing} className="text-gray-500 font-medium hover:text-gray-900 disabled:opacity-50">Back</button>
                                    <button
                                        onClick={handlePlaceOrder}
                                        disabled={isProcessing}
                                        className="btn btn-primary px-8 py-3 text-lg shadow-lg hover:shadow-xl hover:scale-[1.02] transition-all flex items-center gap-2"
                                    >
                                        {isProcessing && <Loader2 className="w-5 h-5 animate-spin" />}
                                        {isProcessing ? 'Processing...' : `Place Order - ₹${total.toLocaleString()}`}
                                    </button>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Right Column: Price Summary Sticky */}
                    <div className="md:col-span-4">
                        <div className="bg-white rounded-xl shadow-sm border border-border p-6 sticky top-24">
                            <h3 className="font-bold text-gray-800 mb-4 border-b pb-2">Price Details</h3>
                            <div className="space-y-3 text-sm">
                                <div className="flex justify-between text-gray-600">
                                    <span>Subtotal ({cart.length} items)</span>
                                    <span>₹{total.toLocaleString()}</span>
                                </div>
                                <div className="flex justify-between text-gray-600">
                                    <span>Delivery Charges</span>
                                    <span className="text-green-600 font-medium">FREE</span>
                                </div>
                                <div className="border-t border-dashed my-2 pt-3 flex justify-between font-bold text-lg text-gray-900">
                                    <span>Total Amount</span>
                                    <span>₹{total.toLocaleString()}</span>
                                </div>
                            </div>

                            <div className="mt-6 bg-green-50 p-3 rounded-lg flex items-start gap-2 text-xs text-green-700">
                                <ShieldCheck className="w-4 h-4 mt-0.5 flex-shrink-0" />
                                <p>Safe and Secure Payments. 100% Authentic products.</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from 'react';
import { useVoice } from '@/context/VoiceContext';
import Link from 'next/link';
import { Shirt, Monitor, Home as HomeIcon, Sparkles, Watch, Footprints, Loader2 } from 'lucide-react';
import { categories } from '@/data/products';
import VoiceHints from '@/components/VoiceHints';
import CategoryQuad from '@/components/CategoryQuad';
import ProductRail from '@/components/ProductRail';

export default function Home() {
  const { speak } = useVoice();
  const [currentSlide, setCurrentSlide] = useState(0);
  const [products, setProducts] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  const heroSlides = [
    {
      id: 1,
      title: "Refined Essentials for Modern Living.",
      subtitle: "Shop Now.",
      image: "/images/modern_home_banner.png",
      link: "/shop",
      color: "bg-secondary"
    },
    {
      id: 2,
      title: "Smart Tech for a Smarter You.",
      subtitle: "Explore Tech.",
      image: "/images/smart_speaker.png",
      link: "/shop?cat=tech",
      color: "bg-blue-50 dark:bg-blue-950"
    },
    {
      id: 3,
      title: "Timeless Elegance on Your Wrist.",
      subtitle: "View Watches.",
      image: "/images/minimalist_watch.png",
      link: "/shop?cat=accessories",
      color: "bg-stone-50 dark:bg-stone-950"
    }
  ];

  useEffect(() => {
    // Speak welcome message on first load
    const timer = setTimeout(() => {
      speak("Welcome to Shopable. Refined essentials for modern living.");
    }, 1000);

    // Slider interval
    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % heroSlides.length);
    }, 6000);

    // Fetch Products
    const fetchProducts = async () => {
      try {
        const res = await fetch('/api/products?limit=100'); // Fetch enough for home page
        if (res.ok) {
          const data = await res.json();
          setProducts(data);
        }
      } catch (error) {
        console.error("Failed to fetch products:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchProducts();

    return () => {
      clearTimeout(timer);
      clearInterval(interval);
    };
  }, []);

  // Filter products for different sections
  const categoryIcons = {
    Apparel: Shirt,
    Tech: Monitor,
    Home: HomeIcon,
    Beauty: Sparkles,
    Watch: Watch,
    Shoes: Footprints,
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="w-10 h-10 text-primary animate-spin" />
      </div>
    );
  }

  const flashDeals = products.filter(p => p.isFlashDeal);
  const mensWear = products.filter(p => p.category === 'Apparel' && p.name.toLowerCase().includes("men"));
  const womensWear = products.filter(p => p.category === 'Apparel' && p.name.toLowerCase().includes("women"));
  const watches = products.filter(p => p.category === 'Watch');
  const shoes = products.filter(p => p.category === 'Shoes');
  const homeDecor = products.filter(p => p.category === 'Home');
  const beauty = products.filter(p => p.category === 'Beauty');
  const tech = products.filter(p => p.category === 'Tech');

  // Helper to get 4 items for quad
  const getQuad = (list) => list.slice(0, 4);

  return (
    <div className="bg-gray-100 min-h-screen">
      <VoiceHints />

      <div className="container py-4 space-y-6">

        {/* Categories Bar */}
        <section className="bg-white p-4 rounded-md shadow-sm flex items-center justify-between overflow-x-auto scrollbar-hide">
          {categories.map((cat) => {
            const Icon = categoryIcons[cat.name] || HomeIcon;
            return (
              <Link key={cat.name} href={`/shop?cat=${cat.name.toLowerCase()}`} className="flex flex-col items-center gap-2 group min-w-[80px]">
                <div className="w-14 h-14 rounded-full bg-gray-50 flex items-center justify-center text-gray-600 group-hover:bg-primary group-hover:text-white transition-all duration-300 shadow-sm border border-gray-100">
                  <Icon className="w-6 h-6" />
                </div>
                <span className="text-xs font-semibold text-gray-700 group-hover:text-primary">{cat.name}</span>
              </Link>
            );
          })}
        </section>

        {/* Full Width Slider + Right Side Quads if desktop */}
        <div className="flex flex-col lg:flex-row gap-4">
          {/* Hero Slider */}
          <div className="lg:w-2/3 h-[300px] md:h-[600px] relative rounded-md overflow-hidden group shadow-sm bg-white">
            {heroSlides.map((slide, index) => (
              <div
                key={slide.id}
                className={`absolute inset-0 transition-opacity duration-1000 ease-in-out flex items-center ${index === currentSlide ? 'opacity-100 z-10' : 'opacity-0 z-0'} ${slide.color}`}
              >
                <div className="absolute inset-0 bg-gradient-to-r from-black/10 to-transparent z-10" />
                <img
                  src={slide.image}
                  alt={slide.title}
                  className="w-full h-full object-cover mix-blend-multiply opacity-90"
                />
                <div className="absolute bottom-10 left-10 z-20 max-w-sm text-foreground bg-white/80 p-6 backdrop-blur-sm rounded-lg shadow-sm">
                  <h2 className="text-3xl font-bold mb-2">{slide.title}</h2>
                  <Link href={slide.link} className="text-sm font-bold uppercase tracking-wide text-primary hover:underline">
                    {slide.subtitle}
                  </Link>
                </div>
              </div>
            ))}
          </div>

          {/* Side Quads (Desktop only mostly) */}
          <div className="lg:w-1/3 flex flex-col gap-4">
            <div className="bg-white p-6 rounded-md shadow-sm flex-1 flex flex-col justify-center items-start">
              <h3 className="text-xl font-bold mb-2">Winter Essentials</h3>
              <div className="grid grid-cols-2 gap-2 w-full mt-2">
                {mensWear.slice(0, 2).map(p => (
                  <img key={p.id} src={p.image} className="bg-gray-50 p-2 rounded w-full h-24 object-contain" />
                ))}
                {womensWear.slice(0, 2).map(p => (
                  <img key={p.id} src={p.image} className="bg-gray-50 p-2 rounded w-full h-24 object-contain" />
                ))}
              </div>
              <Link href="/shop?cat=apparel" className="text-blue-600 text-sm font-medium mt-4">See all offers</Link>
            </div>
            <div className="bg-white p-6 rounded-md shadow-sm flex-1 flex flex-col justify-center items-start">
              <h3 className="text-xl font-bold mb-2">Bestselling Tech</h3>
              <div className="flex gap-2 w-full mt-2 overflow-hidden">
                {tech.slice(0, 3).map(p => (
                  <img key={p.id} src={p.image} className="bg-gray-50 p-2 rounded w-1/3 h-24 object-contain" />
                ))}
              </div>
              <Link href="/shop?cat=tech" className="text-blue-600 text-sm font-medium mt-4">Explore Tech</Link>
            </div>
          </div>
        </div>

        {/* Row 1: Quad Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <CategoryQuad title="Men's Fashion" items={getQuad(mensWear)} link="/shop?cat=apparel" />
          <CategoryQuad title="Women's Fashion" items={getQuad(womensWear)} link="/shop?cat=apparel" />
          <CategoryQuad title="Timepieces" items={getQuad(watches)} link="/shop?cat=watch" />
          <CategoryQuad title="Footwear" items={getQuad(shoes)} link="/shop?cat=shoes" />
        </div>

        {/* Row 2: Horizontal Rail - Flash Deals */}
        <ProductRail title="Flash Deals" products={flashDeals} link="/shop" bgColor="bg-white" />

        {/* Row 3: Quad Cards Mix */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <CategoryQuad title="Home Decor" items={getQuad(homeDecor)} link="/shop?cat=home" />
          <CategoryQuad title="Beauty Picks" items={getQuad(beauty)} link="/shop?cat=beauty" />
          <CategoryQuad title="Smart Devices" items={getQuad(tech)} link="/shop?cat=tech" />

          {/* Simple Banner Card instead of 4th quad */}
          <div className="bg-primary/10 p-6 rounded-lg shadow-sm flex flex-col justify-center items-center text-center">
            <h3 className="text-2xl font-bold text-primary mb-2">Sign in for best experience</h3>
            <Link href="/signin" className="btn btn-primary w-full mt-4 shadow-md">Sign In securely</Link>
          </div>
        </div>

        {/* Row 4: Horizontal Rail - Best Sellers (Mixed) */}
        <ProductRail title="Best Sellers in Sports & Outdoors" products={[...shoes, ...mensWear]} link="/shop" bgColor="bg-white" />

      </div>
    </div>
  );
}

"use client";

import { useState, use, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { products } from '@/data/products';
import { useCart } from '@/context/CartContext';
import { useWishlist } from '@/context/WishlistContext';
import { useVoice } from '@/context/VoiceContext';
import { useToast } from '@/context/ToastContext';
import { useAuth } from '@/context/AuthContext';
import { ChevronRight, Star, Truck, ShieldCheck, Heart, User as UserIcon, MessageSquare } from 'lucide-react';
import ProductRail from '@/components/ProductRail';

export default function ProductDetailsPage({ params }) {
    // Unwrap params using React.use()
    const { id } = use(params);
    const numericId = parseInt(id);
    const router = useRouter();

    // Optimistic initialization from static data
    const [product, setProduct] = useState(() => products.find(p => p.id === numericId));
    const [isLoading, setIsLoading] = useState(true);

    // Reviews State
    const [reviews, setReviews] = useState([]);
    const [loadingReviews, setLoadingReviews] = useState(true);
    const [newReview, setNewReview] = useState({ rating: 5, comment: '' });
    const [submittingReview, setSubmittingReview] = useState(false);

    // Hooks
    const { addToCart } = useCart();
    const { toggleWishlist, isInWishlist } = useWishlist();
    const { speak } = useVoice();
    const { showToast } = useToast();
    const { user, isAuthenticated } = useAuth();

    // State for options (Moved up to avoid ReferenceError in useEffect)
    const [selectedSize, setSelectedSize] = useState(null);
    const [selectedColor, setSelectedColor] = useState(null);

    useEffect(() => {
        const fetchProduct = async () => {
            try {
                // Short timeout for fast fallback
                const controller = new AbortController();
                const timeoutId = setTimeout(() => controller.abort(), 2000);

                const res = await fetch(`/api/products/${numericId}`, {
                    signal: controller.signal,
                    cache: 'no-store'
                });
                clearTimeout(timeoutId);

                if (!res.ok) throw new Error('Failed to fetch');
                const data = await res.json();
                setProduct(data);
            } catch (e) {
                console.warn("Fetch failed, using static data for product details", e);
            } finally {
                setIsLoading(false);
            }
        };

        const fetchReviews = async () => {
            try {
                const res = await fetch(`/api/reviews?productId=${numericId}`);
                if (res.ok) {
                    const data = await res.json();
                    setReviews(data);
                }
            } catch (error) {
                console.error("Failed to fetch reviews", error);
            } finally {
                setLoadingReviews(false);
            }
        };

        fetchProduct();
        fetchReviews();
    }, [numericId]);

    // Voice Command Listener
    useEffect(() => {
        const handleVoiceAddToCart = () => {
            if (product) {
                handleAddToCart();
            }
        };

        window.addEventListener('TRIGGER_ADD_TO_CART', handleVoiceAddToCart);
        return () => window.removeEventListener('TRIGGER_ADD_TO_CART', handleVoiceAddToCart);
    }, [product, selectedSize, selectedColor]); // Re-bind when state changes so closure has latest values

    useEffect(() => {
        if (product) {
            if (product.sizes && !selectedSize) setSelectedSize(product.sizes[0]);
            if (product.colors && !selectedColor) setSelectedColor(product.colors[0]);
        }
    }, [product]);

    if (!product) {
        return (
            <div className="container py-20 text-center">
                <h1 className="text-2xl font-bold mb-4">Product Not Found</h1>
                <Link href="/shop" className="text-primary hover:underline">Back to Shop</Link>
            </div>
        );
    }

    const isWishlisted = isInWishlist(product.id);
    const relatedProducts = products.filter(p => p.category === product.category && p.id !== product.id).slice(0, 5);

    // Initial average from static, but could compute from reviews
    const averageRating = reviews.length > 0
        ? (reviews.reduce((acc, r) => acc + r.rating, 0) / reviews.length).toFixed(1)
        : "4.5"; // Fallback/Default

    const handleAddToCart = () => {
        addToCart(product, { size: selectedSize, color: selectedColor });
        const variantText = (selectedSize ? `size ${selectedSize}, ` : '') + (selectedColor ? `color ${selectedColor}` : '');
        const message = `Added ${product.name} ${variantText} to cart.`;
        speak(message);
        showToast(message, 'success');
    };

    const handleWishlist = () => {
        const added = toggleWishlist(product);
        if (added) {
            speak(`Added ${product.name} to wishlist.`);
            showToast(`Added ${product.name} to wishlist`, 'success');
        } else {
            speak(`Removed ${product.name} from wishlist.`);
            showToast(`Removed ${product.name} from wishlist`, 'info');
        }
    };

    const handleSubmitReview = async (e) => {
        e.preventDefault();
        if (!user) {
            speak("Please sign in to write a review.");
            showToast("Please sign in to write a review", 'error');
            return;
        }

        setSubmittingReview(true);
        try {
            const res = await fetch('/api/reviews', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    productId: numericId,
                    rating: newReview.rating,
                    comment: newReview.comment
                })
            });

            if (res.ok) {
                const savedReview = await res.json();
                setReviews([savedReview, ...reviews]);
                setNewReview({ rating: 5, comment: '' });
                speak("Review submitted successfully.");
                showToast("Review submitted!", 'success');
            } else {
                const err = await res.json();
                throw new Error(err.message || 'Failed to submit review');
            }
        } catch (error) {
            console.error(error);
            showToast(error.message, 'error');
            speak("Failed to submit review.");
        } finally {
            setSubmittingReview(false);
        }
    };

    return (
        <div className="bg-gray-50 min-h-screen pb-12">
            <div className="container py-6">
                {/* Breadcrumbs */}
                <div className="flex items-center gap-2 text-sm text-muted-foreground mb-6">
                    <Link href="/" className="hover:text-primary">Home</Link>
                    <ChevronRight className="w-4 h-4" />
                    <Link href="/shop" className="hover:text-primary">Shop</Link>
                    <ChevronRight className="w-4 h-4" />
                    <span className="font-medium text-foreground">{product.name}</span>
                </div>

                <div className="bg-white rounded-xl shadow-sm border border-border p-6 md:p-8 mb-8">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 lg:gap-12">
                        {/* Image Section */}
                        <div className="space-y-4">
                            <div className="aspect-square bg-secondary rounded-lg overflow-hidden relative group">
                                <img
                                    src={product.image}
                                    alt={product.name}
                                    className="w-full h-full object-cover object-center group-hover:scale-105 transition-transform duration-500"
                                />
                                <button
                                    onClick={handleWishlist}
                                    className={`absolute top-4 right-4 p-3 rounded-full bg-white/90 backdrop-blur-sm shadow-md hover:scale-110 transition-all ${isWishlisted ? 'text-red-500' : 'text-gray-400 hover:text-red-500'}`}
                                >
                                    <Heart className={`w-6 h-6 ${isWishlisted ? 'fill-current' : ''}`} />
                                </button>
                            </div>
                        </div>

                        {/* Details Section */}
                        <div className="flex flex-col">
                            <h1 className="text-3xl md:text-4xl font-bold mb-2 text-gray-900">{product.name}</h1>

                            <div className="flex items-center gap-4 mb-6">
                                <span className="text-2xl font-bold text-primary">₹{product.price.toLocaleString()}</span>
                                <div className="flex items-center gap-1 text-yellow-500 text-sm font-medium bg-yellow-50 px-2 py-1 rounded">
                                    <Star className="w-4 h-4 fill-current" />
                                    <span>{averageRating} ({reviews.length} reviews)</span>
                                </div>
                            </div>

                            <p className="text-gray-600 leading-relaxed mb-8 text-lg">{product.description}</p>

                            {/* Options */}
                            <div className="space-y-6 mb-8">
                                {product.sizes && (
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-2">Select Size</label>
                                        <div className="flex flex-wrap gap-3">
                                            {product.sizes.map(size => (
                                                <button
                                                    key={size}
                                                    onClick={() => setSelectedSize(size)}
                                                    className={`w-12 h-12 rounded-lg border-2 flex items-center justify-center font-medium transition-all ${selectedSize === size
                                                        ? 'border-primary bg-primary text-white shadow-md'
                                                        : 'border-gray-200 hover:border-primary/50 text-gray-600'
                                                        }`}
                                                >
                                                    {size}
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                )}

                                {product.colors && (
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-2">Select Color</label>
                                        <div className="flex flex-wrap gap-3">
                                            {product.colors.map(color => (
                                                <button
                                                    key={color}
                                                    onClick={() => setSelectedColor(color)}
                                                    className={`px-4 py-2 rounded-lg border-2 font-medium transition-all ${selectedColor === color
                                                        ? 'border-primary bg-primary text-white shadow-md'
                                                        : 'border-gray-200 hover:border-primary/50 text-gray-600'
                                                        }`}
                                                >
                                                    {color}
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* Actions */}
                            <div className="mt-auto space-y-4">
                                <button
                                    onClick={handleAddToCart}
                                    className="w-full btn btn-primary text-lg py-4 rounded-xl shadow-lg hover:shadow-xl transition-all active:scale-[0.98]"
                                >
                                    Add to Cart - ₹{product.price.toLocaleString()}
                                </button>

                                {/* Trust Badges */}
                                <div className="grid grid-cols-2 gap-4 mt-6 pt-6 border-t border-gray-100">
                                    <div className="flex items-center gap-3 text-sm text-gray-600">
                                        <div className="p-2 bg-blue-50 rounded-full text-blue-600">
                                            <Truck className="w-5 h-5" />
                                        </div>
                                        <span>Free Delivery</span>
                                    </div>
                                    <div className="flex items-center gap-3 text-sm text-gray-600">
                                        <div className="p-2 bg-green-50 rounded-full text-green-600">
                                            <ShieldCheck className="w-5 h-5" />
                                        </div>
                                        <span>Original Product</span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Reviews Section */}
                <div className="bg-white rounded-xl shadow-sm border border-border p-6 md:p-8 mb-8">
                    <h2 className="text-2xl font-bold mb-6 flex items-center gap-2">
                        <MessageSquare className="w-6 h-6 text-primary" />
                        Customer Reviews
                    </h2>

                    {/* Write Review */}
                    {user ? (
                        <form onSubmit={handleSubmitReview} className="mb-8 bg-gray-50 p-6 rounded-xl border border-gray-100">
                            <h3 className="font-semibold mb-4">Write a Review</h3>
                            <div className="space-y-4">
                                <div>
                                    <label className="block text-sm font-medium mb-1">Rating</label>
                                    <div className="flex gap-2">
                                        {[1, 2, 3, 4, 5].map((star) => (
                                            <button
                                                key={star}
                                                type="button"
                                                onClick={() => setNewReview(prev => ({ ...prev, rating: star }))}
                                                className={`transition-transform hover:scale-110 ${star <= newReview.rating ? 'text-yellow-400' : 'text-gray-300'}`}
                                            >
                                                <Star className="w-6 h-6 fill-current" />
                                            </button>
                                        ))}
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium mb-1">Comment</label>
                                    <textarea
                                        value={newReview.comment}
                                        onChange={(e) => setNewReview(prev => ({ ...prev, comment: e.target.value }))}
                                        className="w-full p-3 rounded-lg border focus:ring-2 focus:ring-primary/20 outline-none min-h-[100px]"
                                        placeholder="Share your experience with this product..."
                                        required
                                    />
                                </div>
                                <button
                                    type="submit"
                                    disabled={submittingReview}
                                    className="btn btn-primary px-6"
                                >
                                    {submittingReview ? 'Posting...' : 'Post Review'}
                                </button>
                            </div>
                        </form>
                    ) : (
                        <div className="mb-8 p-6 bg-gray-50 rounded-xl text-center">
                            <p className="text-muted-foreground mb-4">Please sign in to write a review.</p>
                            <Link href="/signin" className="btn btn-outline">Sign In</Link>
                        </div>
                    )}

                    {/* Reviews List */}
                    <div className="space-y-6">
                        {loadingReviews ? (
                            <div className="text-center py-8">Loading reviews...</div>
                        ) : reviews.length === 0 ? (
                            <div className="text-center py-8 text-muted-foreground">No reviews yet. Be the first to review!</div>
                        ) : (
                            reviews.map((review) => (
                                <div key={review._id} className="border-b last:border-0 pb-6 last:pb-0">
                                    <div className="flex items-center justify-between mb-2">
                                        <div className="flex items-center gap-2">
                                            <div className="w-8 h-8 rounded-full bg-secondary flex items-center justify-center">
                                                <UserIcon className="w-4 h-4 text-gray-600" />
                                            </div>
                                            <span className="font-semibold">{review.userName || 'User'}</span>
                                        </div>
                                        <span className="text-xs text-muted-foreground">
                                            {new Date(review.createdAt).toLocaleDateString()}
                                        </span>
                                    </div>
                                    <div className="flex text-yellow-400 mb-2">
                                        {[...Array(5)].map((_, i) => (
                                            <Star key={i} className={`w-4 h-4 ${i < review.rating ? 'fill-current' : 'text-gray-200 fill-none'}`} />
                                        ))}
                                    </div>
                                    <p className="text-gray-600">{review.comment}</p>
                                </div>
                            ))
                        )}
                    </div>
                </div>

                {/* Related Products */}
                {relatedProducts.length > 0 && (
                    <div className="mt-12">
                        <ProductRail title="You Might Also Like" products={relatedProducts} bgColor="bg-transparent" />
                    </div>
                )}
            </div>
        </div>
    );
}

