"use client";

import React, { useEffect, useState } from 'react';
import { X, CheckCircle, AlertCircle, Info } from 'lucide-react';

export default function Toast({ message, type = 'info', isVisible, onClose }) {
    const [show, setShow] = useState(false);

    useEffect(() => {
        if (isVisible) {
            setShow(true);
        } else {
            // Small delay to allow exit animation
            const timer = setTimeout(() => setShow(false), 300);
            return () => clearTimeout(timer);
        }
    }, [isVisible]);

    if (!show && !isVisible) return null;

    const bgColors = {
        success: 'bg-green-600',
        error: 'bg-red-600',
        info: 'bg-blue-600',
        warning: 'bg-amber-500'
    };

    const icons = {
        success: <CheckCircle className="w-5 h-5" />,
        error: <AlertCircle className="w-5 h-5" />,
        info: <Info className="w-5 h-5" />,
        warning: <AlertCircle className="w-5 h-5" />
    };

    return (
        <div
            className={`fixed bottom-4 right-4 z-50 flex items-center md:min-w-[300px] p-4 rounded-lg shadow-lg text-white transform transition-all duration-300 ease-in-out ${bgColors[type] || bgColors.info} ${isVisible ? 'translate-y-0 opacity-100' : 'translate-y-2 opacity-0'}`}
            role="alert"
        >
            <div className="mr-3">
                {icons[type] || icons.info}
            </div>
            <div className="flex-1 mr-2 font-medium">
                {message}
            </div>
            <button
                onClick={onClose}
                className="p-1 rounded-full hover:bg-white/20 transition-colors"
                aria-label="Close notification"
            >
                <X className="w-4 h-4" />
            </button>
        </div>
    );
}

"use client";

import React, { useEffect, useRef, useState } from 'react';
import { useGesture } from '@/context/GestureContext';

export default function VirtualCursor() {
    const { isGestureEnabled, status, cursor } = useGesture();
    const [lastClickTime, setLastClickTime] = useState(0);

    // Only render if enabled and active
    if (!isGestureEnabled || status !== 'active') return null;

    // Handle Clicking
    useEffect(() => {
        if (cursor.isClicking) {
            const now = Date.now();
            // Debounce clicks (prevent spamming 60 clicks/sec)
            if (now - lastClickTime > 500) {
                const element = document.elementFromPoint(cursor.x, cursor.y);
                if (element) {
                    console.log("Virtual Click on:", element);
                    // Try to click the element or its closest interactive parent
                    const interactive = element.closest('button, a, input, [role="button"]');
                    if (interactive) {
                        interactive.click();
                        interactive.focus(); // Good for inputs

                        // Add visual ripple effect? (Optional)
                    } else {
                        element.click();
                    }
                }
                setLastClickTime(now);
            }
        }
    }, [cursor.isClicking, cursor.x, cursor.y, lastClickTime]);

    return (
        <div
            style={{
                position: 'fixed',
                top: 0,
                left: 0,
                transform: `translate(${cursor.x}px, ${cursor.y}px)`,
                width: '30px',
                height: '30px',
                borderRadius: '50%',
                border: `3px solid ${cursor.isClicking ? '#22c55e' : '#ef4444'}`, // Green when clicking, Red otherwise
                backgroundColor: cursor.isClicking ? 'rgba(34, 197, 94, 0.3)' : 'rgba(239, 68, 68, 0.1)',
                pointerEvents: 'none', // Critical: Let clicks pass through! But wait, we are manually clicking.
                // Actually, we use elementFromPoint, so we MUST ignore this cursor div.
                zIndex: 9999,
                transition: 'transform 0.05s linear, border-color 0.2s',
                marginTop: '-15px', // Center pointer
                marginLeft: '-15px',
                boxShadow: '0 0 10px rgba(0,0,0,0.3)'
            }}
        >
            <div className="absolute top-1/2 left-1/2 w-1 h-1 bg-white rounded-full transform -translate-x-1/2 -translate-y-1/2" />
            <span className="absolute top-full left-1/2 transform -translate-x-1/2 mt-1 text-[10px] bg-black/50 text-white px-1 rounded whitespace-nowrap">
                {cursor.pinchDistance}px
            </span>
        </div>
    );
}

